const settings = $('Agency Settings').item.json;
const raw = $('New Property Enquiry').item.json;
const body = (raw && typeof raw.body === 'object' && raw.body) ? raw.body : raw;

const pick = (...keys) => {
  for (const k of keys) {
    const v = body[k];
    if (v !== undefined && v !== null && String(v).trim()) return String(v).trim();
  }
  return '';
};

const fullName = pick('name', 'full_name', 'fullname', 'contact_name');
const firstName = pick('first_name', 'firstname') || fullName.split(' ')[0] || '';
const lastName = pick('last_name', 'lastname') || fullName.split(' ').slice(1).join(' ');
const name = fullName || [firstName, lastName].filter(Boolean).join(' ');
const email = pick('email', 'email_address').toLowerCase();

let phone = pick('phone', 'telephone', 'mobile', 'phone_number', 'whatsapp_number');
phone = phone.replace(/[^\d+]/g, '');
if (phone.startsWith('00')) phone = '+' + phone.slice(2);
if (phone && !phone.startsWith('+')) {
  const cc = String(settings.defaultCountryCode || '').replace(/[^\d+]/g, '');
  phone = cc + phone.replace(/^0+/, '');
}
if (phone && !/^\+[1-9]\d{6,14}$/.test(phone)) phone = '';

const known = new Set(['name', 'full_name', 'fullname', 'contact_name', 'first_name', 'firstname', 'last_name', 'lastname', 'email', 'email_address', 'phone', 'telephone', 'mobile', 'phone_number', 'whatsapp_number', 'message', 'enquiry', 'comments', 'portal', 'source', 'listing_reference', 'property_reference', 'reference', 'enquiry_id', 'id']);
const extras = Object.entries(body)
  .filter(([k, v]) => !known.has(String(k).toLowerCase()) && v !== null && v !== undefined && String(v).trim())
  .map(([k, v]) => String(k).replace(/_/g, ' ') + ': ' + (Array.isArray(v) ? v.join(', ') : String(v)))
  .join('\n');

return {
  json: {
    enquiry_id: pick('enquiry_id', 'id') || String($execution.id) + '-' + String($itemIndex),
    received_at: new Date().toISOString(),
    portal: pick('portal', 'source') || 'website',
    listing_reference: pick('listing_reference', 'property_reference', 'reference').toUpperCase(),
    name,
    first_name: firstName,
    last_name: lastName,
    email,
    phone,
    message: pick('message', 'enquiry', 'comments'),
    extra_answers: extras || 'No extra fields on the form'
  }
};

