parameters.jsCode:
const enquiry = $('Normalise The Enquiry').item.json;

const hasOutput = !!($json.output && typeof $json.output === 'object');
const ai = hasOutput ? $json.output : {};
const aiStatus = $json.ai_status || (hasOutput ? 'ok' : 'failed');
let aiError = $json.ai_error || '';
if (aiStatus !== 'ok' && !aiError) {
  aiError = ($json.error && ($json.error.message || $json.error)) || 'model returned no output';
}

const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? Math.round(n) : 0;
};
const clean = (v, fallback) => (v === null || v === undefined || String(v).trim() === '') ? fallback : String(v).trim();

let readiness = Number(ai.readiness_score);
if (!Number.isFinite(readiness)) readiness = 0;
readiness = Math.max(0, Math.min(100, Math.round(readiness)));

const areas = clean(ai.preferred_areas, '')
  .split(',')
  .map((a) => a.trim().toLowerCase())
  .filter(Boolean);

return {
  json: {
    ...enquiry,
    transaction_type: clean(ai.transaction_type, 'unknown').toLowerCase(),
    budget_min: num(ai.budget_min),
    budget_max: num(ai.budget_max),
    min_bedrooms: num(ai.min_bedrooms),
    preferred_areas: areas.join(', '),
    preferred_area_list: areas,
    property_type: clean(ai.property_type, 'unknown').toLowerCase(),
    move_timeframe: clean(ai.move_timeframe, 'unknown'),
    finance_status: clean(ai.finance_status, 'unknown'),
    chain_status: clean(ai.chain_status, 'unknown'),
    wants_viewing: clean(ai.wants_viewing, 'unknown'),
    readiness_score: readiness,
    summary: clean(ai.summary, aiStatus === 'ok' ? '' : 'AI reading failed, read this enquiry by hand.'),
    ai_status: aiStatus,
    ai_error: clean(String(aiError), '')
  }
};

const brief = $('Shape The Buyer Brief').first().json;
const settings = $('Agency Settings').first().json;
const matchLine = Number(settings.matchThreshold) || 45;
const viewingLine = Number(settings.viewingThreshold) || 70;
const nurtureLine = Number(settings.nurtureThreshold) || 40;

const text = (v) => String(v === null || v === undefined ? '' : v).toLowerCase().trim();
const money = (v) => {
  const n = Number(String(v === null || v === undefined ? '' : v).replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : 0;
};

const rows = $input.all().map((i) => (i && i.json) || {});
const stockFailed = rows.some((r) => r && r.error);
const stockRows = rows.filter((r) => Object.keys(r).some((k) => k !== 'error' && k !== 'pairedItem' && String(r[k] === null || r[k] === undefined ? '' : r[k]).trim() !== ''));
const stockStatus = stockFailed ? 'unreadable' : (stockRows.length ? 'ok' : 'empty');
const stockNote = stockStatus === 'unreadable'
  ? 'the property sheet could not be read'
  : 'no properties were loaded from the sheet';

const wanted = brief.transaction_type === 'rent' ? 'rent' : 'sale';
const scored = [];

for (const p of stockRows) {
  const status = text(p.status);
  if (status && status !== 'available') continue;
  const listingType = text(p.listing_type) || 'sale';
  if (listingType !== wanted) continue;

  const price = money(p.price);
  const beds = Number(p.bedrooms) || 0;
  const where = text(p.address) + ' ' + text(p.postcode);
  let score = 0;
  const reasons = [];

  if (brief.budget_max > 0) {
    if (price > 0 && price <= brief.budget_max * 1.05 && price >= brief.budget_min * 0.9) {
      score += 35;
      reasons.push('inside budget');
    } else if (price > 0 && price <= brief.budget_max * 1.15) {
      score += 15;
      reasons.push('just over budget');
    }
  } else {
    score += 15;
    reasons.push('no budget given');
  }

  if (brief.min_bedrooms > 0) {
    if (beds >= brief.min_bedrooms) {
      score += 25;
      reasons.push(beds + ' bed');
    }
  } else {
    score += 10;
  }

  const areas = Array.isArray(brief.preferred_area_list) ? brief.preferred_area_list : [];
  if (areas.length) {
    if (areas.some((a) => a && where.includes(a))) {
      score += 25;
      reasons.push('right area');
    }
  } else {
    score += 10;
  }

  if (brief.property_type && brief.property_type !== 'unknown' && text(p.property_type) === brief.property_type) {
    score += 15;
    reasons.push(brief.property_type);
  }

  if (brief.listing_reference && text(p.reference) === text(brief.listing_reference)) {
    score = 100;
    reasons.unshift('the listing they enquired about');
  }

  scored.push({
    reference: String(p.reference === null || p.reference === undefined ? '' : p.reference),
    address: String(p.address === null || p.address === undefined ? '' : p.address),
    postcode: String(p.postcode === null || p.postcode === undefined ? '' : p.postcode),
    price,
    bedrooms: beds,
    url: String(p.url === null || p.url === undefined ? '' : p.url),
    match_score: Math.min(100, score),
    match_reasons: reasons.join(', ')
  });
}

const matches = scored
  .filter((m) => m.match_score >= matchLine)
  .sort((a, b) => b.match_score - a.match_score)
  .slice(0, 3);

let verdict = 'WATCH';
if (brief.ai_status !== 'ok') verdict = 'UNSCORED';
else if (stockStatus !== 'ok') verdict = 'NO_STOCK';
else if (brief.readiness_score >= viewingLine && matches.length > 0) verdict = 'VIEWING';
else if (brief.readiness_score >= nurtureLine) verdict = 'NURTURE';

const top = matches[0] || null;
const noMatchNote = stockStatus === 'ok' ? 'nothing in stock cleared the match threshold' : stockNote;

return [{
  json: {
    ...brief,
    verdict,
    stock_status: stockStatus,
    properties_considered: stockRows.length,
    match_count: matches.length,
    matches,
    matched_references: matches.map((m) => m.reference).join(', '),
    top_match_reference: top ? top.reference : '',
    top_match_address: top ? top.address : '',
    top_match_price: top ? top.price : 0,
    top_match_url: top ? top.url : '',
    top_match_reasons: top ? top.match_reasons : noMatchNote,
    viewing_threshold: viewingLine,
    nurture_threshold: nurtureLine
  }
}];

const brief = $('Match Properties To The Brief').first().json;
const settings = $('Agency Settings').first().json;
const duration = Number(settings.viewingDurationMinutes) || 45;
const firstHour = Number(settings.firstSlotHour) || 10;
const lastHour = Number(settings.lastSlotHour) || 18;

const rows = $input.all().map((i) => (i && i.json) || {});
const diaryFailed = rows.some((r) => r && r.error);
const events = rows.filter((r) => r && (r.start || r.end));
const diaryStatus = diaryFailed ? 'unreadable' : (events.length ? 'ok' : 'empty');

const busy = events
  .map((e) => ({
    start: Date.parse(e.start ? (e.start.dateTime || e.start.date || '') : ''),
    end: Date.parse(e.end ? (e.end.dateTime || e.end.date || '') : '')
  }))
  .filter((b) => Number.isFinite(b.start) && Number.isFinite(b.end));

const slots = [];
if (diaryStatus !== 'unreadable') {
  for (let day = 1; day <= 7 && slots.length < 2; day++) {
    const dayStart = $now.plus({ days: day });
    if (dayStart.weekday > 6) continue;
    for (let hour = firstHour; hour * 60 + duration <= lastHour * 60 && slots.length < 2; hour++) {
      const start = dayStart.set({ hour: hour, minute: 0, second: 0, millisecond: 0 });
      const end = start.plus({ minutes: duration });
      const s = start.toMillis();
      const e = end.toMillis();
      if (busy.some((b) => s < b.end && e > b.start)) continue;
      slots.push({ start_iso: start.toISO(), end_iso: end.toISO(), label: start.toFormat('cccc d LLLL, HH:mm') });
    }
  }
}

const needsManualSlot = diaryStatus === 'unreadable' || slots.length < 2;
while (slots.length < 2) {
  const start = $now.plus({ days: slots.length + 1 }).set({ hour: firstHour, minute: 0, second: 0, millisecond: 0 });
  slots.push({ start_iso: start.toISO(), end_iso: start.plus({ minutes: duration }).toISO(), label: start.toFormat('cccc d LLLL, HH:mm') + ' (placeholder, not checked against the diary)' });
}

return [{
  json: {
    ...brief,
    viewing_duration_minutes: duration,
    diary_status: diaryStatus,
    needs_manual_slot: needsManualSlot,
    diary_events_read: busy.length,
    slot_one_start: slots[0].start_iso,
    slot_one_end: slots[0].end_iso,
    slot_one_label: slots[0].label,
    slot_two_start: slots[1].start_iso,
    slot_two_end: slots[1].end_iso,
    slot_two_label: slots[1].label
  }
}];

